    pass


def target():
    return 1


@mock.patch("__main__.target", lambda: 3)
class MockedB(MockedA):
    def test_value(self):
        return target()


print("valid patch method", MockedB().test_value(), "outside", target())


def factory(value):
    @mock.patch("__main__.target", lambda: value)
    class Nested(MockedA):
        def test_value(self):
            return target()

    return Nested


